E=NC.E
med.GENERIC.update({"psy":"Classic psychedelics activate serotonin 5-HT2A receptors in the cortex, loosening the brain's usual filtering of perception and thought.","emp":"Empathogens release serotonin, dopamine and noradrenaline and trigger oxytocin release.","alc":"Ethanol enhances GABA-A and blocks NMDA receptors and is broken down by the liver at a roughly fixed rate.","del":"Deliriants block muscarinic acetylcholine receptors in the brain and body.","oth":"Its effects come from its own specific mechanism, described above."})
G=lambda w:E(f"Medically, onset reflects absorption. {{met}} {w[0]}",w[1],w[2],w[3],w[4],w[5])
med.EXTRA.update({
"psy":G(["Heart rate and blood pressure rise slightly and pupils widen.","Early nausea and yawning are common.","At the peak, sensory and thought changes are strongest; the main dangers are psychological (panic, confusion) and accidents, not organ toxicity, for classic psychedelics.","Risks rise with a history of psychosis or bipolar disorder, and with lithium or certain antidepressants.","As levels fall, perception normalizes gradually, but sleep may be hard.","A small number develop lasting visual disturbances (HPPD) or prolonged anxiety."]),
"emp":G(["Serotonin floods synapses, heart rate rises and the jaw tightens.","Body temperature regulation begins to fail in heat.","At the peak, risks include overheating, low blood sodium from overdrinking, and serotonin syndrome.","Repeated redosing raises toxicity without raising pleasure.","As serotonin is depleted, mood falls.","Low mood midweek after use is common."]),
"alc":G(["Blood alcohol rises fastest on an empty stomach.","Judgment is affected before coordination.","At high levels breathing and gag reflexes are suppressed.","Alcohol poisoning kills by stopped breathing or choking on vomit.","Blood alcohol can keep rising after drinking stops.","Hangover reflects dehydration, acetaldehyde, and poor sleep."]),
"del":G(["Anticholinergic signs appear: dry mouth, flushed skin, wide pupils, fast heartbeat.","Bladder and gut slow.","At the peak, true delirium: confusion and realistic hallucinations people believe are real.","Overheating, seizures and heart rhythm problems can be fatal.","The comedown is long, often a day or more of confusion.","Memory of the episode is usually poor."]),
"oth":G(["Early effects depend on the substance.","Body signs are described above.","Peak risks are described above.","Mixing with other drugs raises risk.","Effects fade as the drug is cleared.","Lingering effects vary."])})
V="Why the same amount affects people differently: body size, tolerance, genetics, mood and setting, health conditions, medicines (especially antidepressants and lithium), and product purity all change the effect."
med.VARY.update({k:V for k in N2})
med.VARY["alc"]="Why the same amount affects people differently: body size, sex (women reach higher blood alcohol from the same drinks), food, speed of drinking, tolerance, genetics (for example, ALDH2 variants common in East Asian people cause flushing), age, and medicines all change the effect."
L.CLS.update({"psy":"At lower doses psychedelics bring brighter colors, mood changes and new ways of thinking. At higher doses, strong visual changes, loss of the usual sense of self, and time distortion occur. At very high levels, people may lose touch with reality entirely, and panic, confusion and risky behavior become more likely.",
"emp":"At lower doses empathogens bring warmth, openness and mild stimulation. At higher doses, stimulation, jaw clenching, sweating and overheating rise while the pleasant effects do not increase much. At very high levels, serotonin toxicity, overheating, seizures and collapse can occur.",
"alc":"At lower amounts alcohol brings relaxation and talkativeness. At higher amounts, slurred speech, poor balance, poor judgment and memory blackouts follow. At very high levels, vomiting, unconsciousness, slowed breathing and death from alcohol poisoning occur.",
"del":"At lower doses deliriants cause drowsiness, dry mouth and a fast heartbeat. At higher doses, confusion, blurred vision and hallucinations start. At very high levels, full delirium with realistic hallucinations, overheating, seizures and dangerous heart rhythms occur; no one finds this pleasant.",
"oth":"At lower doses effects are mild; at higher doses side effects and toxicity dominate, as described for each substance."})
NC.TOL.update({"psy":"Tolerance to classic psychedelics builds within a day and lasts several days, with cross-tolerance between them.","emp":"Tolerance to the warmth fades with frequent use while side effects remain.","alc":"Tolerance hides impairment but not organ damage; daily drinking leads to dependence, and stopping suddenly can cause seizures and delirium tremens.","del":"Tolerance develops to some effects, but delirium risk remains.","oth":"Tolerance and dependence vary by substance."})
NC.SAFE.update({"psy":("psychedelic-safety.md","Psychedelic safety"),"emp":("empathogen-safety.md","Empathogen (MDMA) safety"),"alc":("alcohol-safety.md","Alcohol safety"),"del":("deliriant-safety.md","Deliriant safety"),"oth":("other-psychoactives-safety.md","Other psychoactives safety")})
NC.OD.update({"psy":"## Signs that someone needs help\n\n- Seizures, very high temperature, or chest pain (especially with NBOMes or 2C drugs).\n- Severe panic that does not calm with reassurance, or danger to self or others.\n- Unresponsiveness.\n\n## What to do\n\n- Call 911 for physical symptoms. Good Samaritan laws in most US states protect callers.\n- Move to a quiet, safe place and speak calmly.\n- Stay with them; do not leave them alone.\n",
"emp":"## Signs that someone needs help\n\n- Very high temperature, confusion, or stopping sweating.\n- Severe headache, vomiting and confusion after drinking lots of water (low sodium).\n- Muscle rigidity, jerking, or seizures.\n- Collapse.\n\n## What to do\n\n- Call 911 and tell responders what was taken.\n- Move to a cool place; cool the skin.\n- Do not give large amounts of water.\n",
"alc":"## Signs of alcohol poisoning\n\n- Cannot be woken.\n- Slow or irregular breathing.\n- Vomiting while passed out.\n- Cold, clammy, pale or bluish skin; seizures.\n\n## What to do\n\n- Call 911. Do not let them 'sleep it off'.\n- Put them in the recovery position.\n- Stay with them. Cold showers and coffee do not help.\n",
"del":"## Signs that someone needs help\n\n- Confusion, talking to people who are not there.\n- Hot, dry, flushed skin; very fast heartbeat.\n- Seizures or collapse.\n\n## What to do\n\n- Call 911 or Poison Control (1-800-222-1222).\n- Keep them safe and calm; they may not know where they are.\n",
"oth":"## Signs that someone needs help\n\n- Seizures, unresponsiveness, chest pain, or severe confusion.\n\n## What to do\n\n- Call 911 or Poison Control (1-800-222-1222).\n- Recovery position if drowsy.\n"})
